function words(which){
 const prefix=which===0?'first':'second',field=$('#'+prefix+'Transcript'),box=$('#'+prefix+'Words');
 box.replaceChildren();
 for(const match of field.value.matchAll(/\S+/gu)){
  const word=document.createElement('button');word.type='button';word.textContent=match[0];
  word.setAttribute('aria-label',ex(0)+' '+match[0]);
  word.onclick=()=>{
   const editor=document.createElement('input');editor.type='text';editor.value=match[0];editor.className='word-editor';editor.lang=target;
   editor.setAttribute('aria-label',ex(0));editor.style.width=Math.max(7,Math.min(24,match[0].length+3))+'ch';
   word.replaceWith(editor);editor.focus();editor.select();
   const commit=()=>{
    const replacement=editor.value.trim();const text=field.value;
    if(replacement&&text.slice(match.index,match.index+match[0].length)===match[0]){
     field.value=text.slice(0,match.index)+replacement+text.slice(match.index+match[0].length);
     attempts[which]=field.value.trim();
    }
    words(which);
   };
   editor.addEventListener('blur',commit,{once:true});
   editor.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();editor.blur()}if(e.key==='Escape'){editor.value=match[0];editor.blur()}});
  };
  box.append(word);
 }
}
